"""Self-contained, offline replay. User text is inserted only with textContent."""
import json

def render(results):
    payload = json.dumps(results).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return TEMPLATE.replace("__RESULTS__", payload)

